import numpy as np


def construct(budget_seconds, start):
    """Code Zero: keep the start if there is one, otherwise 32 small equal circles on a grid."""
    if start is not None:
        return np.asarray(start, dtype=float)
    k = int(np.ceil(np.sqrt(32)))
    pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:32]
    return np.array([[x, y, 0.02] for x, y in pts])

import numpy as np
import time
from scipy.optimize import minimize


def _unpack(z, n):
    z = z.reshape(n, 3)
    return z[:, 0], z[:, 1], z[:, 2]


def _constraints_violation(x, y, r):
    n = len(x)
    v = 0.0
    # walls
    v += np.sum(np.maximum(0, r - x) ** 2)
    v += np.sum(np.maximum(0, x + r - 1) ** 2)
    v += np.sum(np.maximum(0, r - y) ** 2)
    v += np.sum(np.maximum(0, y + r - 1) ** 2)
    # pairwise
    for i in range(n):
        dx = x[i] - x[i + 1:]
        dy = y[i] - y[i + 1:]
        d = np.sqrt(dx * dx + dy * dy)
        s = r[i] + r[i + 1:]
        ov = np.maximum(0, s - d)
        v += np.sum(ov ** 2)
    return v


def _objective(zflat, n):
    x, y, r = _unpack(zflat, n)
    v = _constraints_violation(x, y, r)
    return -np.sum(r) + 1e6 * v


def _repair(z, n):
    z = np.array(z, dtype=float).reshape(n, 3)
    x = z[:, 0].copy(); y = z[:, 1].copy(); r = z[:, 2].copy()
    r = np.maximum(r, 1e-9)
    for _ in range(300):
        changed = False
        for i in range(n):
            if x[i] - r[i] < 0:
                x[i] = r[i]; changed = True
            if x[i] + r[i] > 1:
                x[i] = 1 - r[i]; changed = True
            if y[i] - r[i] < 0:
                y[i] = r[i]; changed = True
            if y[i] + r[i] > 1:
                y[i] = 1 - r[i]; changed = True
            if r[i] > 0.5:
                r[i] = 0.5; changed = True
        for i in range(n):
            for j in range(i + 1, n):
                dx = x[i] - x[j]; dy = y[i] - y[j]
                d = np.hypot(dx, dy)
                s = r[i] + r[j]
                if d < s:
                    excess = s - d
                    tot = r[i] + r[j]
                    if tot > 0:
                        r[i] -= excess * (r[i] / tot) * 0.5 + 1e-12
                        r[j] -= excess * (r[j] / tot) * 0.5 + 1e-12
                    r[i] = max(r[i], 1e-9)
                    r[j] = max(r[j], 1e-9)
                    changed = True
        if not changed:
            break
    r = np.maximum(r, 1e-9)
    for i in range(n):
        r[i] = min(r[i], x[i], 1 - x[i], y[i], 1 - y[i])
    r = np.maximum(r, 1e-9)
    r = np.maximum(r - 1e-10, 1e-9)
    out = np.column_stack([x, y, r])
    return out, float(np.sum(r))


def _initial_configs(n, rng):
    configs = []

    def jitter(pts):
        pts = np.array(pts, dtype=float)
        pts += rng.uniform(-0.01, 0.01, pts.shape)
        return np.clip(pts, 0.0, 1.0)

    pts = []
    for j in range(6):
        for i in range(6):
            if len(pts) < n:
                pts.append(((i + 0.5 + (0.5 if j % 2 else 0)) / 6.0,
                            (j + 0.5) / 6.0))
    configs.append(jitter(pts[:n]))

    pts = []
    for j in range(4):
        for i in range(8):
            if len(pts) < n:
                pts.append(((i + 0.5 + (0.5 if j % 2 else 0)) / 8.0,
                            (j + 0.5) / 4.0))
    configs.append(jitter(pts[:n]))

    pts = []
    for j in range(5):
        for i in range(7):
            if len(pts) < n:
                pts.append(((i + 0.5) / 7.0, (j + 0.5) / 5.0))
    configs.append(jitter(pts[:n]))

    pts = rng.uniform(0.05, 0.95, size=(n, 2))
    configs.append(pts)

    return configs


def _polish(z, n, deadline, t0):
    """SLSQP polish on the feasible manifold: maximize sum r subject to constraints,
    using smooth penalty gradient descent instead. We use a direct SLSQP formulation."""
    from scipy.optimize import minimize as _min

    x0 = z[:, 0].copy(); y0 = z[:, 1].copy(); r0 = z[:, 2].copy()

    # variables: x, y, r
    def unpack(v):
        return v[:n], v[n:2*n], v[2*n:]

    def neg_sum(v):
        return -np.sum(v[2*n:])

    def neg_sum_grad(v):
        g = np.zeros(3*n)
        g[2*n:] = -1.0
        return g

    cons = []
    # wall constraints (inequality >= 0)
    for i in range(n):
        cons.append({'type': 'ineq', 'fun': (lambda v, i=i: v[i] - v[2*n+i])})
        cons.append({'type': 'ineq', 'fun': (lambda v, i=i: 1 - v[i] - v[2*n+i])})
        cons.append({'type': 'ineq', 'fun': (lambda v, i=i: v[n+i] - v[2*n+i])})
        cons.append({'type': 'ineq', 'fun': (lambda v, i=i: 1 - v[n+i] - v[2*n+i])})
    # pairwise
    def make_pair(i, j):
        def f(v):
            dx = v[i] - v[j]; dy = v[n+i] - v[n+j]
            d = np.sqrt(dx*dx + dy*dy)
            return d - v[2*n+i] - v[2*n+j]
        return f
    for i in range(n):
        for j in range(i + 1, n):
            cons.append({'type': 'ineq', 'fun': make_pair(i, j)})

    v0 = np.concatenate([x0, y0, r0])
    bounds = [(0, 1)] * (2*n) + [(1e-9, 0.5)] * n

    try:
        res = _min(neg_sum, v0, jac=neg_sum_grad, method='SLSQP',
                   bounds=bounds, constraints=cons,
                   options={'maxiter': 500, 'ftol': 1e-12})
        x, y, r = unpack(res.x)
        z2 = np.column_stack([x, y, r])
        return z2
    except Exception:
        return z


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32
    deadline = t0 + budget_seconds - 0.6

    rng = np.random.default_rng(12345)

    best = None
    best_score = -1.0

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.shape == (n, 3):
            rep, sc = _repair(s, n)
            if sc > best_score:
                best = rep
                best_score = sc

    bounds = [(0.0, 1.0), (0.0, 1.0), (1e-6, 0.5)] * n

    configs = _initial_configs(n, rng)
    # also try scaled copies of current best
    if best is not None:
        configs.insert(0, best[:, :2].copy())

    for pts in configs:
        if time.process_time() > deadline:
            break
        z0 = np.column_stack([pts, np.full(n, 0.05)]).ravel()
        try:
            res = minimize(_objective, z0, args=(n,), method='L-BFGS-B',
                           bounds=bounds,
                           options={'maxiter': 2000, 'ftol': 1e-12})
            rep, sc = _repair(res.x, n)
        except Exception:
            continue
        if sc > best_score:
            best = rep
            best_score = sc

    if best is None:
        k = int(np.ceil(np.sqrt(n)))
        pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:n]
        best = np.array([[x, y, 0.02] for x, y in pts])
        best_score = float(best[:, 2].sum())

    # SLSQP polish on best
    if time.process_time() < deadline:
        pol = _polish(best, n, deadline, t0)
        rep, sc = _repair(pol, n)
        if sc > best_score:
            best = rep
            best_score = sc

    return best
